331: // publishPending publishes pending facts oldest-first until the outbox is empty.
332: // It returns nil when a read finds nothing pending, the permanent poison error
333: // for a row Core cannot decode or map, and errDeviceFactRetry for a transient
334: // failure after logging it. When a stored row cannot be decoded, the read also
335: // returns the decodable rows older than it, and publishPending publishes and
336: // deletes that prefix before it returns the poison error, so only the poison row
337: // and the rows behind it stay blocked. A transient read failure is always
338: // retryable and carries no prefix; only the outbox's own permanent row class
339: // faults the relay. It deliberately returns on the first transient failure so no
340: // row is skipped and the retry starts again from the oldest pending row.
341: func (relay *DeviceFactRelay) publishPending(ctx context.Context) error {
342: 	for {
343: 		if ctxErr := ctx.Err(); ctxErr != nil {
344: 			return ctxErr
345: 		}
346: 		pending, listErr := relay.outbox.ListPendingDeviceFacts(ctx, relay.batchSize)
347: 		if listErr != nil {
348: 			// A row whose stored bytes cannot be decoded is deterministic, so the
349: 			// relay faults and preserves it instead of retrying a decode that can
350: 			// never succeed. Decoding stopped at that row, so pending is the valid
351: 			// older prefix; deliver it first, then fault, so the poison row and the
352: 			// rows behind it are the only ones still blocked.
353: 			if poisonErr := asInvalidOutboxRowPoison(listErr); poisonErr != nil {
354: 				if publishErr := relay.publishBatch(ctx, pending); publishErr != nil {
355: 					return publishErr
356: 				}
357: 				return poisonErr
358: 			}
359: 			// Every other read failure is transient and carries no prefix.
360: 			relay.logRetry(ctx, deviceFactStageList, deviceFactCodeListFailed, "", "")
361: 			return errDeviceFactRetry
362: 		}
363: 		if len(pending) == 0 {
364: 			return nil
365: 		}
366: 		if err := relay.publishBatch(ctx, pending); err != nil {
367: 			return err
368: 		}
369: 	}
370: }
