372: // publishBatch publishes and deletes one decoded batch in enqueue order. It
373: // stops at the first retryable failure so no row is skipped and the retry
374: // restarts from the oldest row the batch left pending.
375: func (relay *DeviceFactRelay) publishBatch(
376: 	ctx context.Context,
377: 	pending []devices.PendingDeviceFact,
378: ) error {
379: 	for _, item := range pending {
380: 		if err := relay.publishPendingFact(ctx, item); err != nil {
381: 			return err
382: 		}
383: 	}
384: 	return nil
385: }
