387: // publishPendingFact maps one pending fact, publishes it and deletes its row only
388: // after the broker acknowledged it into the expected stream. A duplicate
389: // acknowledgement is a success: the fact is already stored under the same
390: // Nats-Msg-Id. The row is deleted only after the acknowledgement, so a failed
391: // publish or a failed delete leaves the durable fact pending and the next
392: // attempt reuses the same identity and bytes.
393: func (relay *DeviceFactRelay) publishPendingFact(
394: 	ctx context.Context,
395: 	pending devices.PendingDeviceFact,
396: ) error {
397: 	message, mappingErr := mapPendingDeviceFact(relay.validator, pending)
398: 	if mappingErr != nil {
399: 		return mappingErr
400: 	}
401: 	publishCtx, cancelPublish := context.WithTimeout(ctx, relay.publishTimeout)
402: 	ack, publishErr := relay.publish(publishCtx, message.natsMessage())
403: 	cancelPublish()
404: 	if publishErr != nil {
405: 		relay.logPublishRetry(ctx, message, publishErr)
406: 		return errDeviceFactRetry
407: 	}
408: 	if ack == nil {
409: 		relay.logRetry(ctx, deviceFactStageAck, deviceFactCodeAckMissing, message.family, message.sourceID)
410: 		return errDeviceFactRetry
411: 	}
412: 	// The expected-stream header makes the broker reject a publication into any
413: 	// other stream, so an acknowledgement naming another stream means the fact is
414: 	// not where Core must delete it: keep the row and retry rather than lose it.
415: 	if ack.Stream != DeviceFactStreamName {
416: 		relay.logRetry(ctx, deviceFactStageAck, deviceFactCodeUnexpectedStream, message.family, message.sourceID)
417: 		return errDeviceFactRetry
418: 	}
419: 	if deleteErr := relay.outbox.DeleteDeviceFact(ctx, message.factID); deleteErr != nil {
420: 		relay.logRetry(ctx, deviceFactStageDelete, deviceFactCodeDeleteFailed, message.family, message.sourceID)
421: 		return errDeviceFactRetry
422: 	}
423: 	return nil
424: }
