427: // attempt is shutdown rather than a broker fault, so it is not logged; a publish
428: // bound expiry is logged, because a stalled broker is exactly the diagnostic an
429: // operator needs.
430: func (relay *DeviceFactRelay) logPublishRetry(
431: 	ctx context.Context,
432: 	message deviceFactMessage,
433: 	publishErr error,
434: ) {
435: 	if errors.Is(publishErr, context.Canceled) {
436: 		return
437: 	}
438: 	relay.logRetry(ctx, deviceFactStagePublish, deviceFactCodePublishFailed, message.family, message.sourceID)
439: }
